fn shell_game(n: i32, x: i8) -> i8 {
    // Each pair of moves (odd i then even i+1) implements the cycle
    //   0 → 2 → 1 → 0.
    // Call that composite mapping g.  g has order 3.
    //
    // If n is even, we perform n/2 copies of g.
    // If n is odd, we perform (n-1)/2 copies of g, then one extra odd-step swap f1.
    //
    //   g(x):
    //     0 → 2
    //     1 → 0
    //     2 → 1
    //
    //   g^2(x):
    //     0 → 1
    //     1 → 2
    //     2 → 0
    //
    //   f1(x) (the odd-step swap 0↔1):
    //     0 ↔ 1, 2 ↦ 2

    // Number of complete (odd,even) move‐pairs
    let pairs = n / 2;
    // g has period 3, so reduce
    let rem = pairs % 3;

    // Apply g^rem to x
    let mut pos = match rem {
        0 => x,
        1 => match x {
            0 => 2,
            1 => 0,
            2 => 1,
            _ => unreachable!(),
        },
        2 => match x {
            0 => 1,
            1 => 2,
            2 => 0,
            _ => unreachable!(),
        },
        _ => unreachable!(),
    };

    // If there's an extra odd‐numbered move, apply f1: swap 0↔1
    if n % 2 != 0 {
        pos = match pos {
            0 => 1,
            1 => 0,
            2 => 2,
            _ => unreachable!(),
        };
    }

    pos
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn small_examples() {
        // Manual simulation for small n, x
        let mut state;
        for x in 0..=2 {
            for n in 1..=10 {
                state = x;
                for i in 1..=n {
                    if i % 2 == 1 {
                        // odd: swap 0<->1
                        state = match state {
                            0 => 1,
                            1 => 0,
                            _ => 2,
                        };
                    } else {
                        // even: swap 1<->2
                        state = match state {
                            1 => 2,
                            2 => 1,
                            _ => 0,
                        };
                    }
                }
                assert_eq!(
                    shell_game(n, x),
                    state,
                    "Failed for n={}, x={}: got {}, expected {}",
                    n,
                    x,
                    shell_game(n, x),
                    state
                );
            }
        }
    }

    #[test]
    fn large_n() {
        // Check periodicity: after 6 moves we return to the same position
        for x in 0..=2 {
            let p0 = shell_game(0, x); // initially x
            let p6 = shell_game(6, x);
            assert_eq!(p0, p6);
        }
    }
}